/* Key findings panel */
.findings-title{
  margin-bottom: 0;
  font-size: 16px;
  font-weight: 600;
}

.findings-note{
  font-size: 11px;
  font-weight: 400;
  color: rgba(114,132,154,0.7);
  margin-left: 8px;
}

.findings-list{
  list-style: none;
  margin: 12px 0 0;
  padding: 0;
  column-count: 2;
  column-gap: 24px;
}

.findings-list li{
  break-inside: avoid;
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 7px 10px;
  margin-bottom: 6px;
  border-radius: 4px;
  background: #f9fbfd;
  border-left: 3px solid transparent;
  font-size: 13px;
  line-height: 1.45;
  color: #2a2a2a;
}

.findings-list li i{
  margin-top: 2px;
  font-size: 14px;
}

.findings-list li b{
  font-weight: 600;
}

.finding-danger  { border-left-color: #e63757; background: #fdedef; }
.finding-danger i  { color: #e63757; }
.finding-warning { border-left-color: #f6b343; background: #fdf5e6; }
.finding-warning i { color: #e8a020; }
.finding-info    { border-left-color: #3f87f5; background: #edf4fe; }
.finding-info i    { color: #3f87f5; }
.finding-success { border-left-color: #00c9a7; background: #e9faf6; }
.finding-success i { color: #00c9a7; }

@media (max-width: 1200px){
  .findings-list{ column-count: 1; }
}

/* Negative values in red */
.neg-val{
  color: #e63757 !important;
}

/* Winner report suggestions */
.ra-list{
  margin-top: 12px;
  border-top: 1px solid #edf2f9;
}

.ra-group-row{
  padding: 8px 10px 4px;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: rgba(114,132,154,0.9);
}

.ra-row{
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 5px 10px;
  border-bottom: 1px solid #f2f5fa;
}

.ra-row:hover{
  background: #f9fbfd;
}

.ra-field{
  width: 260px;
  flex: 0 0 260px;
  color: rgba(84,84,95,0.85);
  font-size: 13px;
}

.ra-value{
  flex: 1;
  font-weight: 500;
  color: #2a2a2a;
  font-size: 13px;
}

.ra-note{
  font-weight: 400;
  font-size: 12px;
}

.ra-copy{
  border: none;
  background: transparent;
  color: #72849a;
  cursor: pointer;
  padding: 2px 6px;
  border-radius: 4px;
  flex: 0 0 auto;
}

.ra-copy:hover{
  background: #edf4fe;
  color: #3f87f5;
}

